package com.sistemahospitalar.hospital.service; import com.sistemahospitalar.hospital.model.*; import com.sistemahospitalar.hospital.repository.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class InternacaoService {private final InternacaoRepository repo; private final QuartoRepository quartos; public InternacaoService(InternacaoRepository repo,QuartoRepository quartos){this.repo=repo;this.quartos=quartos;} public Internacao salvar(Internacao i){Quarto q=quartos.findById(i.getQuarto().getId()).orElseThrow(()->new NoSuchElementException("Quarto não encontrado.")); q.ocuparLeito(); quartos.save(q); i.setQuarto(q); return repo.save(i);} public List<Internacao> listar(){return repo.findAll();}}
